CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 INTEGER DEFAULT 'd', c1 INT COLLATE NOCASE, c2 VARCHAR(10));
INSERT OR IGNORE INTO t0(c0, c1, c2) VALUES(531.84, x'', x'3ad8');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 VARCHAR(10) CHECK(c0 IS NULL OR length(c0) < 40), c1 TEXT, ref INTEGER REFERENCES t0(id));
INSERT OR IGNORE INTO t1(c0, c1, ref) VALUES(-41, -3, 8);
INSERT OR IGNORE INTO t1(c0, c1, ref) VALUES(589.5150, x'd1d96a2fea', 7);
INSERT OR IGNORE INTO t1(c0, c1, ref) VALUES(2, x'11a5046e', 1);
CREATE TABLE t2(id INTEGER PRIMARY KEY, c0 VARCHAR(10), c1 TEXT UNIQUE, ref INTEGER REFERENCES t1(id));
INSERT OR IGNORE INTO t2(c0, c1, ref) VALUES('omega', 690, 5);
SELECT length('nu'), upper('nu'), lower('nu'), substr('nu', -1, 3), instr('nu', 'upsilon'), replace('nu', 'a', '_'), trim('nu'), ltrim('nu', 'ab'), hex('nu'), quote('nu'), unicode('nu'), 'nu' LIKE '%', 'nu' GLOB '?', char(81, 826), 'nu' || 'upsilon', 'nu' < 'upsilon', 'nu' = 'upsilon' COLLATE NOCASE;
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', -3, 5), instr('pi', 'iota'), replace('pi', 'é', '_'), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE '%é%', 'pi' GLOB '?', char(86, 211), 'pi' || 'iota', 'pi' < 'iota', 'pi' = 'iota' COLLATE NOCASE;
SELECT length('psi'), upper('psi'), lower('psi'), substr('psi', 2, 0), instr('psi', 'pi'), replace('psi', 'e', '_'), trim('psi'), ltrim('psi', 'ab'), hex('psi'), quote('psi'), unicode('psi'), 'psi' LIKE '%a_', 'psi' GLOB '*', char(66, 437), 'psi' || 'pi', 'psi' < 'pi', 'psi' = 'pi' COLLATE NOCASE;
SELECT length('日本'), upper('日本'), lower('日本'), substr('日本', -2, 2), instr('日本', 'über'), replace('日本', 'é', ''), trim('日本'), ltrim('日本', 'ab'), hex('日本'), quote('日本'), unicode('日本'), '日本' LIKE '_', '日本' GLOB '*', char(78, 956), '日本' || 'über', '日本' < 'über', '日本' = 'über' COLLATE NOCASE;
SELECT length('sigma'), upper('sigma'), lower('sigma'), substr('sigma', -2, 2), instr('sigma', 'phi'), replace('sigma', '', ''), trim('sigma'), ltrim('sigma', 'ab'), hex('sigma'), quote('sigma'), unicode('sigma'), 'sigma' LIKE 'a%', 'sigma' GLOB '*', char(81, 888), 'sigma' || 'phi', 'sigma' < 'phi', 'sigma' = 'phi' COLLATE NOCASE;
SELECT length('1e3'), upper('1e3'), lower('1e3'), substr('1e3', 0, 3), instr('1e3', '0x1F'), replace('1e3', 'e', ''), trim('1e3'), ltrim('1e3', 'ab'), hex('1e3'), quote('1e3'), unicode('1e3'), '1e3' LIKE 'A%', '1e3' GLOB '?', char(79, 243), '1e3' || '0x1F', '1e3' < '0x1F', '1e3' = '0x1F' COLLATE NOCASE;
SELECT length('gamma'), upper('gamma'), lower('gamma'), substr('gamma', 3, 4), instr('gamma', 'café'), replace('gamma', 'a', 'XY'), trim('gamma'), ltrim('gamma', 'ab'), hex('gamma'), quote('gamma'), unicode('gamma'), 'gamma' LIKE 'A%', 'gamma' GLOB '*[a-m]*', char(76, 603), 'gamma' || 'café', 'gamma' < 'café', 'gamma' = 'café' COLLATE NOCASE;
SELECT id, nullif(-(ref), x'9e0b' IS NULL), coalesce(coalesce(c0, 0.1 IS NULL), typeof(0)) FROM t1 ORDER BY id, c0, c1 DESC, ref;
SELECT CASE WHEN nullif(typeof(0), -(3)) THEN nullif(nullif(-778, '日本'), 1) ELSE NULL BETWEEN x'' AND typeof(0.1) END, CASE WHEN x'c9c5c1' IS NULL BETWEEN 'theta' BETWEEN -749 AND NULL AND nullif('a%b', -97) THEN CASE WHEN 9223372036854775807 THEN x'' ELSE -516.50 END IS NULL ELSE iif(NOT 0, NULL IN (123456789012, -4, 'delta'), x'd074886da6') END;
